+
+impl ExactCoveredProjection {
+    fn new() -> Self {
+        Self {
+            words: Vec::new(),
+            bytes: Vec::new(),
+        }
+    }
+
+    fn f64(&mut self, value: f64) {
+        self.words.push(value.to_bits());
+    }
+
+    fn option_f64(&mut self, value: Option<f64>) {
+        self.words.push(u64::from(value.is_some()));
+        if let Some(value) = value {
+            self.f64(value);
+        }
+    }
+
+    fn text(&mut self, value: &str) {
+        self.words.push(value.len() as u64);
+        self.bytes.extend_from_slice(value.as_bytes());
+    }
+
+    fn tag(&mut self, value: u8) {
+        self.bytes.push(value);
+    }
+
+    fn floats(&mut self, values: impl IntoIterator<Item = f64>) {
+        self.words.extend(values.into_iter().map(f64::to_bits));
+    }
+}
+
+fn water_branch_tag(branch: WaterBranch) -> u8 {
+    match branch {
+        WaterBranch::ConstitutiveLaw => 0,
+        WaterBranch::AuthorizationActiveOrTie => 1,
+        WaterBranch::Condensation => 2,
+    }
+}
+
+fn gas_branch_tag(branch: V10LeafGasBranch) -> u8 {
+    match branch {
+        V10LeafGasBranch::Inactive => 0,
+        V10LeafGasBranch::ExactZeroPar => 1,
+        V10LeafGasBranch::RespirationDominated => 2,
+        V10LeafGasBranch::PositiveAssimilation => 3,
+    }
