+use super::*;
+
+pub(super) fn assert_rainy_n2_s6_route_replay(
+    column: &CoveredColumnInputs,
+    trial: &[f64],
+    caps: &CoveredWaterCaps,
+) {
+    let mut rainy = column.clone();
+    rainy.top_rain_kg_m2_tile = 0.1;
+    rainy.occupancies[1].liquid_capacity_kg_m2_plant = 1.0;
+    for caps in [None, Some(caps)] {
+        let validated = ValidatedCoveredEvaluationInputs::try_new(&rainy, caps)
+            .expect("validated rainy N2/S6 replay fixture");
+        let base = ValidatedCoveredJacobianBase::evaluate(&validated, trial)
+            .expect("rainy N2/S6 replay base");
+        let frozen = freeze_covered_branches(&base.evaluation);
+        let graph = covered_component_dependency_graph(2, 6);
+        let plan = graph
+            .component_replay_plan(0, 2)
+            .expect("rainy upper-wet execution plan");
+        assert!(plan.routing_replay_from == Some(0));
+        assert!(plan.occupancy_replay[1].vapor.iter().all(|execute| *execute));
+        assert!(plan.occupancy_replay[1].emax.iter().all(|execute| *execute));
+        assert!(plan.occupancy_replay[1].hydraulic);
+        assert!(plan.occupancy_replay[1]
+            .energy
+            .iter()
+            .all(|execute| *execute));
+        assert!(plan.longwave);
+
+        let column_index = 8;
+        let perturbation = f64::EPSILON.sqrt() * trial[column_index].abs().max(1.0);
+        for direction in [-1.0, 1.0] {
+            let mut probe = trial.to_vec();
+            probe[column_index] += direction * perturbation;
+            let replayed = evaluate_covered_component_temperature_replay(
+                &validated,
+                &probe,
+                &frozen,
+                &base.evaluation,
+                0,
+                2,
+                plan,
+                &base.replay_base_nodes,
+            )
+            .expect("rainy N2/S6 replay evaluation");
+            let complete = evaluate_covered_column_validated(
+                &validated,
+                &probe,
+                Some(&frozen),
+                None,
