+fn update_bytes(digest: &mut Sha256, field_count: &mut u64, bytes: &[u8]) {
+    digest.update(bytes.len().to_le_bytes());
+    digest.update(bytes);
+    *field_count += 1;
+}
+
+fn update_f64(digest: &mut Sha256, field_count: &mut u64, value: f64) {
+    update_bytes(digest, field_count, &value.to_bits().to_le_bytes());
+}
+
+fn update_f64s(
+    digest: &mut Sha256,
+    field_count: &mut u64,
+    values: impl IntoIterator<Item = f64>,
+) {
+    for value in values {
+        update_f64(digest, field_count, value);
+    }
+}
