+pub(crate) fn record_component_replay_internal_candidate(
+    solve_class: CoveredComponentReplaySolveClass,
+    transaction_identity: &str,
+    candidate: &CoveredColumnCandidate,
+    accepted_owner: CoveredComponentReplayExactProjection,
+) {
+    let candidate = exact_component_replay_candidate_projection(candidate);
+    let dense_trajectory = PENDING_COMPONENT_REPLAY_DENSE_TRACE
+        .with(|trace| std::mem::take(&mut *trace.borrow_mut()));
+    COVERED_COMPONENT_DEPENDENCY_REPLAY_AUDIT.with(|audit| {
+        if let Some(audit) = audit.borrow_mut().as_mut() {
+            audit.internal_records.push(CoveredComponentReplayInternalRecord {
+                solve_class,
+                transaction_identity: transaction_identity.to_owned(),
+                candidate,
+                accepted_owner,
+                dense_trajectory,
+            });
+        }
+    });
+}
+
+pub(crate) fn component_replay_exact_bytes_projection(
+    bytes: &[u8],
+) -> CoveredComponentReplayExactProjection {
+    let mut digest = Sha256::new();
+    digest.update(bytes.len().to_le_bytes());
+    digest.update(bytes);
+    CoveredComponentReplayExactProjection {
+        field_count: 1,
+        sha256: format!("{:x}", digest.finalize()),
+    }
