+pub(crate) fn exact_component_replay_potential_owner_projection(
+    identity: &crate::RuntimeTileIdentity,
+    beginning: &CoveredColumnInputs,
+    accepted: &CoveredColumnCandidate,
+    request_batch: &crate::PotentialWaterRequestBatch,
+    vegetation: &crate::PotentialCoveredVegetationOperands,
+    roots: &BTreeMap<(String, String), crate::RootRuntimeIdentity>,
+    gas_branches: &[[crate::V10LeafGasBranch; 2]],
+    map_identity: &CoveredComponentReplayMapIdentity,
+) -> CoveredComponentReplayExactProjection {
+    let mut digest = Sha256::new();
+    let mut fields = 0;
+    update_bytes(&mut digest, &mut fields, &identity.transaction_id.0.to_le_bytes());
+    update_bytes(&mut digest, &mut fields, &identity.soil_thermal_transaction_id.0.to_le_bytes());
+    for value in [&identity.lse_owner_id.0, &identity.hydrology_owner_id.0,
+        &identity.soil_thermal_owner_id.0, &identity.vegetation_owner_id.0,
+        &identity.biogeochemistry_owner_id.0, identity.configuration_sha256.as_str(),
+        identity.beginning_lse_state_sha256.as_str(),
+        identity.beginning_hydrology_snapshot_sha256.as_str(),
+        identity.beginning_soil_thermal_state_sha256.as_str(),
+        identity.beginning_vegetation_state_sha256.as_str(),
+        identity.beginning_biogeochemistry_state_sha256.as_str(), identity.ofe_id.as_str(),
+        identity.tile_id.as_str(), identity.surface_id.as_str(), &identity.ground_source_id.0] {
+        update_bytes(&mut digest, &mut fields, value.as_bytes());
+    }
+    update_f64s(&mut digest, &mut fields, [identity.tile_fraction, identity.interval_s]);
+    update_bytes(&mut digest, &mut fields, &[identity.surface_class as u8,
+        identity.ground_source_type as u8]);
+    for value in [identity.ground_source_tile_id.as_ref().map(TileId::as_str),
+        identity.ground_soil_layer_id.as_ref().map(SoilLayerId::as_str)] {
+        update_bytes(&mut digest, &mut fields, value.unwrap_or("").as_bytes());
+    }
+    update_covered_input(&mut digest, &mut fields, beginning);
+    let candidate = exact_component_replay_candidate_projection(accepted);
+    update_bytes(&mut digest, &mut fields, candidate.sha256.as_bytes());
+    update_bytes(&mut digest, &mut fields,
+        &serde_json::to_vec(&request_batch.requests).expect("request projection"));
+    update_bytes(&mut digest, &mut fields, request_batch.potential_signature_sha256.as_str().as_bytes());
+    update_bytes(&mut digest, &mut fields,
+        &serde_json::to_vec(vegetation).expect("potential vegetation projection"));
+    update_bytes(&mut digest, &mut fields, &roots.len().to_le_bytes());
+    for ((occupancy, layer), root) in roots {
+        for value in [occupancy, layer, &root.solver_occupancy_id, &root.requesting_owner_id.0,
+            &root.occupancy_id.0, &root.layer_id.0, &root.source_id.0] {
+            update_bytes(&mut digest, &mut fields, value.as_bytes());
+        }
+    }
+    update_bytes(&mut digest, &mut fields, &gas_branches.len().to_le_bytes());
+    for branches in gas_branches { update_bytes(&mut digest, &mut fields,
+        &branches.map(|branch| branch as u8)); }
+    update_bytes(&mut digest, &mut fields, &map_identity.ordinal.to_le_bytes());
+    update_bytes(&mut digest, &mut fields, map_identity.identity.as_bytes());
+    CoveredComponentReplayExactProjection { field_count: fields,
+        sha256: format!("{:x}", digest.finalize()) }
+}
